-- Look & feel: "glass" — translucent, blurred, rounded. Tuned for Intel UHD.
-- Colors come from ../colors.lua, generated by matugen from the wallpaper
-- (scripts/wallpaper.sh). Fallback = a deep forest-green palette.

local fallback = {
    primary            = "9cd67d",
    primary_container  = "3f7a2a",
    secondary          = "bccbb0",
    outline            = "8c9388",
    outline_variant    = "43493f",
    surface            = "11140f",
    shadow             = "000000",
}

local ok, generated = pcall(require, "colors")
local c = (ok and type(generated) == "table") and generated or fallback

local function rgba(hex, alpha) return "rgba(" .. hex .. alpha .. ")" end

hl.config({
    general = {
        gaps_in     = 5,
        gaps_out    = 12,
        border_size = 2,
        col = {
            active_border   = { colors = { rgba(c.primary, "ff"), rgba(c.primary_container, "ff") }, angle = 45 },
            inactive_border = rgba(c.outline_variant, "aa"),
        },
        resize_on_border = true,
        allow_tearing    = false,
        layout           = "dwindle",
    },

    decoration = {
        rounding       = 14,
        rounding_power = 2.5,

        -- global opacity stays 1.0; translucency is opt-in per app (conf/rules.lua)
        active_opacity   = 1.0,
        inactive_opacity = 1.0,

        dim_special = 0.35,

        shadow = {
            enabled      = true,
            range        = 18,
            render_power = 3,
            offset       = "0 4",
            color          = rgba(c.shadow, "66"),
            color_inactive = rgba(c.shadow, "33"),
        },

        -- Kawase blur. size × passes is the GPU cost; 7×2 is smooth on UHD 620.
        blur = {
            enabled           = true,
            size              = 7,
            passes            = 2,
            new_optimizations = true,
            xray              = false,   -- floating glass shows windows behind it
            ignore_opacity    = true,
            noise             = 0.02,
            contrast          = 0.9,
            brightness        = 0.85,    -- darker glass = better text contrast
            vibrancy          = 0.25,    -- keeps the wallpaper greens lush
            vibrancy_darkness = 0.15,
            popups            = true,
            special           = false,   -- expensive
        },
    },

    dwindle = {
        preserve_split = true,
    },

    misc = {
        force_default_wallpaper  = 0,
        disable_hyprland_logo    = true,
        disable_splash_rendering = true,
        background_color         = "0x" .. c.surface,
        focus_on_activate        = true,
        key_press_enables_dpms   = true,
        mouse_move_enables_dpms  = true,
    },

    cursor = {
        hide_on_key_press = true,
    },
})
